dtsPropsFor.OverallRisk:
/** The mountain. OverallRisk reads name-independent fields: isLive, risk, isDemo. */
  hill: {
    slug: string;
    name: string;
    region: string;
    /** False for display markers: they show the fixed level and one line, no score. */
    isLive: boolean;
    stats: { elevationM: number; meanSlopeDeg: number; areaKm2: number };
    /** The overall score, 0 to 1, and its level. High and Extreme get the border and tint. */
    risk: { score: number; level: "low" | "moderate" | "high" | "extreme" };
    /** The top five trails (the TrailList item shape). OverallRisk does not render them; [] is fine. */
    trails: unknown[];
    preventative: string[];
    /** True adds the line "Illustrative scores until the trail model lands." */
    isDemo: boolean;
  };

dtsPropsFor.TrailList:
/** The top five, riskiest first, lettered A to E. Each item: */
  trails: Array<{
    id: string;
    /** A for the riskiest, E for the fifth. The row and the map marker share it. */
    letter: "A" | "B" | "C" | "D" | "E";
    name: string;
    /** 0 to 1, two decimals when shown. */
    score: number;
    level: "low" | "moderate" | "high" | "extreme";
    /** Hillside slope at the riskiest point, in degrees. */
    slopeDeg: number;
    /** The driver that contributes most, in plain words ("Steep slopes", "Drainage channel"). */
    primaryFactor: string;
    /** [longitude, latitude] of the marker. */
    center: [number, number];
    /** Camera zoom that View flies to, about 13. */
    zoom: number;
    /** GeoJSON LineString of the trail, or null. */
    geom: { type: "LineString"; coordinates: [number, number][] } | null;
  }>;
  /** The row last viewed (accent left border), or null. */
  selected: "A" | "B" | "C" | "D" | "E" | null;
  /** Called by a row's View button with its letter. */
  onView: (letter: "A" | "B" | "C" | "D" | "E") => void;

dtsPropsFor.AgentCard:
agent: {
    id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
    status: "idle" | "running" | "done" | "error";
    /** One line under the card's name. */
    summary: string;
    /** The full reasoning trace, one step per entry, shown when expanded. */
    trace: string[];
    /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
    startedAt: number | null;
    finishedAt: number | null;
  };
  /** Shows the trace directly beneath the card. The parent keeps one open at a time. */
  expanded: boolean;
  /** An idle agent a failed run never reached: its status reads "not reached". */
  notReached: boolean;
  onToggle: () => void;

dtsPropsFor.AgentPipeline:
state: {
    orchestrator: "idle" | "running" | "done" | "error";
    /** One entry per agent. Terrain, Weather, and Trails run together; then Synthesizer; then alertWriter (Mass Alert Writer). */
    agents: {
      terrain: {
        id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
        status: "idle" | "running" | "done" | "error";
        /** One line under the card's name. */
        summary: string;
        /** The full reasoning trace, one step per entry, shown when expanded. */
        trace: string[];
        /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
        startedAt: number | null;
        finishedAt: number | null;
      };
      weather: {
        id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
        status: "idle" | "running" | "done" | "error";
        /** One line under the card's name. */
        summary: string;
        /** The full reasoning trace, one step per entry, shown when expanded. */
        trace: string[];
        /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
        startedAt: number | null;
        finishedAt: number | null;
      };
      trails: {
        id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
        status: "idle" | "running" | "done" | "error";
        /** One line under the card's name. */
        summary: string;
        /** The full reasoning trace, one step per entry, shown when expanded. */
        trace: string[];
        /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
        startedAt: number | null;
        finishedAt: number | null;
      };
      synthesizer: {
        id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
        status: "idle" | "running" | "done" | "error";
        /** One line under the card's name. */
        summary: string;
        /** The full reasoning trace, one step per entry, shown when expanded. */
        trace: string[];
        /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
        startedAt: number | null;
        finishedAt: number | null;
      };
      alertWriter: {
        id: "terrain" | "weather" | "trails" | "synthesizer" | "alertWriter";
        status: "idle" | "running" | "done" | "error";
        /** One line under the card's name. */
        summary: string;
        /** The full reasoning trace, one step per entry, shown when expanded. */
        trace: string[];
        /** Epoch ms, or null before the agent starts. The card shows the duration once both are set. */
        startedAt: number | null;
        finishedAt: number | null;
      };
    };
    /** Null until the Mass Alert Writer finishes. Render them with ReactiveMeasures. */
    measures: Array<{
    /** Groups render in this order: closures, evacuation, rescue, monitoring, coordination, public. */
    category: "closures" | "evacuation" | "rescue" | "monitoring" | "coordination" | "public";
    title: string;
    detail: string;
    /** Deadline chip, such as "Now" (drawn solid), "Within 1 h", "Next morning". Public items show "Draft, not sent" instead. */
    when: string;
    /** The trail it concerns (its badge takes the trail's level color from `trails`), or null. */
    letter: "A" | "B" | "C" | "D" | "E" | null;
  }> | null;
    /** The Orchestrator's line when orchestrator is "error". */
    error: string | null;
  };
  /* initialPipelineState() returns the idle state; usePipeline(hill) plays a scripted run. */

dtsPropsFor.ReactiveMeasures:
